//! The grammar's long word lists. Generated by `oracle/blade-grammar.ts`
//! from the `blade` grammar Shiki 4.6.0 bundles; do not edit.
//!
//! A table holds every word of its lists, sorted, in one text.
//! Each word has the list that holds it first, in the grammar's order.

/// Which table a word list is in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Table {
    /// The lists of the grammar's `support_head` entry.
    SupportHead,
    /// The lists of the grammar's `support_output` entry.
    SupportOutput,
    /// The lists of the grammar's `support_tail` entry.
    SupportTail,
    /// The lists of the grammar's `constants` entry.
    Constants,
    /// The lists of the grammar's `class-builtin` entry.
    Classes,
}

impl Table {
    /// The table's words.
    pub(crate) fn words(self) -> &'static Words {
        match self {
            Table::SupportHead => &SUPPORTHEAD,
            Table::SupportOutput => &SUPPORTOUTPUT,
            Table::SupportTail => &SUPPORTTAIL,
            Table::Constants => &CONSTANTS,
            Table::Classes => &CLASSES,
        }
    }
}

